const img = document.getElementById('img-missing-alt');
const alt = img.getAttribute('alt');
return !!alt && alt === 'A red fox resting in a grassy meadow under sunlight' && img.dataset.ai4a11yProcessed === 'done';

const svg = document.getElementById('svg-missing-alt');
const title = svg.querySelector(':scope > title');
return svg.getAttribute('role') === 'img' &&
  !!title &&
  title.textContent === 'A red fox resting in a grassy meadow under sunlight' &&
  svg.dataset.ai4a11yProcessed === 'done';

const canvas = document.getElementById('canvas-missing-desc');
const label = canvas.getAttribute('aria-label');
return canvas.getAttribute('role') === 'img' &&
  label === 'A red fox resting in a grassy meadow under sunlight' &&
  canvas.dataset.ai4a11yProcessed === 'done';

const video = document.getElementById('video-missing-desc');
const label = video.getAttribute('aria-label');
return label === 'Ocean waves crashing gently against rocky coastal cliffs' &&
  video.dataset.ai4a11yDescribed === 'done';

const imgExist = document.getElementById('img-existing-alt');
const imgDec = document.getElementById('img-decorative');
const svgExist = document.getElementById('svg-existing-label');
const svgDec = document.getElementById('svg-decorative');
const canvasExist = document.getElementById('canvas-existing-desc');

const imgExistOk = imgExist.getAttribute('alt') === 'Snowy mountain peaks at sunrise' && !imgExist.dataset.ai4a11yProcessed;
const imgDecOk = imgDec.getAttribute('alt') === '' && !imgDec.dataset.ai4a11yProcessed;
const svgExistOk = svgExist.getAttribute('aria-label') === 'Regional sanctuary boundaries' && !svgExist.querySelector('title') && !svgExist.dataset.ai4a11yProcessed;
const svgDecOk = svgDec.getAttribute('aria-hidden') === 'true' && !svgDec.hasAttribute('role') && !svgDec.dataset.ai4a11yProcessed;
const canvasExistOk = canvasExist.getAttribute('aria-label') === 'Quarterly forest canopy coverage' && !canvasExist.dataset.ai4a11yProcessed;

return imgExistOk && imgDecOk && svgExistOk && svgDecOk && canvasExistOk;

const h1 = document.querySelector('header h1');
const navLinks = document.querySelectorAll('nav a');
const footer = document.getElementById('footer-copy');
