harness.enable:
window.__genAltPrev = [];

const results = await axe.run({
  runOnly: { type: 'rule', values: Object.keys(m.axeHandlers) }
});
for (const violation of results.violations) {
  const handler = m.axeHandlers[violation.id];
  if (!handler) continue;
  for (const node of violation.nodes) {
    try {
      const el = document.querySelector(node.target[0]);
      if (!el || el.dataset.ai4a11yProcessed) continue;
      window.__genAltPrev.push({
        el,
        kind: 'axe',
        alt: el.getAttribute('alt'),
        hadAlt: el.hasAttribute('alt'),
        role: el.getAttribute('role'),
        hadRole: el.hasAttribute('role'),
        hadTitle: !!el.querySelector(':scope > title'),
        titleText: el.querySelector(':scope > title')?.textContent,
        processed: el.dataset.ai4a11yProcessed,
      });
      await handler(el);
    } catch (e) {
      console.error('Handler error:', e);
    }
  }
}

for (const canvas of document.querySelectorAll('canvas:not([data-ai4a11y-processed])')) {
  if (!canvas.getAttribute('aria-label') && !canvas.getAttribute('aria-labelledby') && !canvas.getAttribute('title')) {
    window.__genAltPrev.push({
      el: canvas,
      kind: 'canvas',
      role: canvas.getAttribute('role'),
      hadRole: canvas.hasAttribute('role'),
      ariaLabel: canvas.getAttribute('aria-label'),
      hadAriaLabel: canvas.hasAttribute('aria-label'),
      processed: canvas.dataset.ai4a11yProcessed,
    });
    await m.generateCanvasDescription(canvas);
  }
}

for (const video of document.querySelectorAll('video:not([data-ai4a11y-described])')) {
  if (!video.getAttribute('aria-label') && !video.getAttribute('aria-labelledby') && !video.getAttribute('title')) {
    window.__genAltPrev.push({
      el: video,
      kind: 'video',
      ariaLabel: video.getAttribute('aria-label'),
      hadAriaLabel: video.hasAttribute('aria-label'),
      described: video.dataset.ai4a11yDescribed,
    });
    await m.generateVideoDescription(video);
  }
}

harness.disable:
if (window.__genAltPrev) {
  for (const item of window.__genAltPrev) {
    if (item.kind === 'axe') {
      if (item.hadAlt) item.el.setAttribute('alt', item.alt);
      else item.el.removeAttribute('alt');
      if (item.hadRole) item.el.setAttribute('role', item.role);
      else item.el.removeAttribute('role');
      const titleEl = item.el.querySelector(':scope > title');
      if (item.hadTitle && titleEl) {
        titleEl.textContent = item.titleText;
      } else if (!item.hadTitle && titleEl) {
        titleEl.remove();
      }
      if (item.processed !== undefined) item.el.dataset.ai4a11yProcessed = item.processed;
      else delete item.el.dataset.ai4a11yProcessed;
    } else if (item.kind === 'canvas') {
      if (item.hadRole) item.el.setAttribute('role', item.role);
      else item.el.removeAttribute('role');
      if (item.hadAriaLabel) item.el.setAttribute('aria-label', item.ariaLabel);
      else item.el.removeAttribute('aria-label');
      if (item.processed !== undefined) item.el.dataset.ai4a11yProcessed = item.processed;
      else delete item.el.dataset.ai4a11yProcessed;
    } else if (item.kind === 'video') {
      if (item.hadAriaLabel) item.el.setAttribute('aria-label', item.ariaLabel);
      else item.el.removeAttribute('aria-label');
      if (item.described !== undefined) item.el.dataset.ai4a11yDescribed = item.described;
      else delete item.el.dataset.ai4a11yDescribed;
    }
  }
  delete window.__genAltPrev;
}
